CREATE TABLE IF NOT EXISTS gis_spatial_identity_matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES gis_identity_resolution_runs(id) ON DELETE CASCADE, crosswalk_id uuid REFERENCES gis_identity_crosswalks(id) ON DELETE CASCADE, source_feature_id uuid NOT NULL REFERENCES gis_spatial_features(id) ON DELETE CASCADE, target_provider text NOT NULL, target_provider_feature_id text, name_score numeric(6,5) NOT NULL DEFAULT 0, parent_score numeric(6,5) NOT NULL DEFAULT 0, bbox_score numeric(6,5) NOT NULL DEFAULT 0, centroid_score numeric(6,5) NOT NULL DEFAULT 0, area_score numeric(6,5) NOT NULL DEFAULT 0, composite_score numeric(6,5) NOT NULL DEFAULT 0, confidence text NOT NULL DEFAULT 'Unresolved', review_required boolean NOT NULL DEFAULT true, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now())